-- fix\nSET NAMES utf8mb4;\nCREATE TABLE IF NOT EXISTS guest_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, hotel_id BIGINT UNSIGNED NOT NULL DEFAULT 1, kind ENUM('message','experience') NOT NULL DEFAULT 'message', department VARCHAR(40) NOT NULL DEFAULT 'frontdesk', reference VARCHAR(80), full_name VARCHAR(190), email VARCHAR(190), phone VARCHAR(50), subject VARCHAR(190), message TEXT, rating TINYINT UNSIGNED, status ENUM('new','assigned','resolved','featured','archived') NOT NULL DEFAULT 'new', created_at TIMESTAMP NULL DEFAULT NULL, updated_at TIMESTAMP NULL DEFAULT NULL, deleted_at TIMESTAMP NULL DEFAULT NULL, deleted_by BIGINT UNSIGNED DEFAULT NULL, PRIMARY KEY (id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\nCREATE TABLE IF NOT EXISTS event_requests (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, hotel_id BIGINT UNSIGNED NOT NULL DEFAULT 1, reference VARCHAR(80), full_name VARCHAR(190), email VARCHAR(190), phone VARCHAR(50), event_type VARCHAR(80), event_date DATE, guests INT, venue_preference VARCHAR(80), details TEXT, status ENUM('new','contacted','quoted','confirmed','declined','archived') NOT NULL DEFAULT 'new', created_at TIMESTAMP NULL DEFAULT NULL, updated_at TIMESTAMP NULL DEFAULT NULL, deleted_at TIMESTAMP NULL DEFAULT NULL, deleted_by BIGINT UNSIGNED DEFAULT NULL, PRIMARY KEY (id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\nCREATE TABLE IF NOT EXISTS facility_enquiries (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, hotel_id BIGINT UNSIGNED NOT NULL DEFAULT 1, reference VARCHAR(80), full_name VARCHAR(190), email VARCHAR(190), phone VARCHAR(50), facility VARCHAR(80), preferred_date DATE, details TEXT, status ENUM('new','contacted','quoted','confirmed','declined','archived') NOT NULL DEFAULT 'new', created_at TIMESTAMP NULL DEFAULT NULL, updated_at TIMESTAMP NULL DEFAULT NULL, deleted_at TIMESTAMP NULL DEFAULT NULL, deleted_by BIGINT UNSIGNED DEFAULT NULL, PRIMARY KEY (id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\nCREATE TABLE IF NOT EXISTS news_posts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, hotel_id BIGINT UNSIGNED NOT NULL DEFAULT 1, created_by BIGINT UNSIGNED DEFAULT NULL, title VARCHAR(190) NOT NULL, slug VARCHAR(190), category ENUM('news','update','opportunity','recruitment','employee') NOT NULL DEFAULT 'news', excerpt TEXT, body LONGTEXT, image VARCHAR(255), department VARCHAR(40), status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', published_at DATETIME DEFAULT NULL, views INT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP NULL DEFAULT NULL, updated_at TIMESTAMP NULL DEFAULT NULL, deleted_at TIMESTAMP NULL DEFAULT NULL, deleted_by BIGINT UNSIGNED DEFAULT NULL, PRIMARY KEY (id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\nSET @sql = (SELECT IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE table_schema='hotelpardise_system' AND table_name='payments' AND column_name='invoice_id')=0,'ALTER TABLE payments ADD COLUMN invoice_id BIGINT UNSIGNED DEFAULT NULL','SELECT 1')); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;\nSET @sql = (SELECT IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE table_schema='hotelpardise_system' AND table_name='payments' AND column_name='gateway_result')=0,'ALTER TABLE payments ADD COLUMN gateway_result LONGTEXT DEFAULT NULL','SELECT 1')); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;\nSET @sql = (SELECT IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE table_schema='hotelpardise_system' AND table_name='payments' AND column_name='verified_at')=0,'ALTER TABLE payments ADD COLUMN verified_at DATETIME DEFAULT NULL','SELECT 1')); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;\nUPDATE payments SET status='successful', verified_at=NOW() WHERE status='pending';\nSELECT 'done';\n